class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(arr):
    if not arr or arr[0] is None:
        return None
    root = TreeNode(arr[0])
    queue = [root]
    i = 1
    while i < len(arr) and queue:
        node = queue.pop(0)
        if i < len(arr):
            left_val = arr[i]
            i += 1
            if left_val is not None:
                node.left = TreeNode(left_val)
                queue.append(node.left)
        if i < len(arr):
            right_val = arr[i]
            i += 1
            if right_val is not None:
                node.right = TreeNode(right_val)
                queue.append(node.right)
    return root


def lowest_common_ancestor(root_arr, p, q):
    root = build_tree(root_arr)

    def dfs(node):
        if node is None or node.val == p or node.val == q:
            return node
        left = dfs(node.left)
        right = dfs(node.right)
        if left and right:
            return node
        return left if left else right

    result = dfs(root)
    return result.val if result else None

